package me.pipi.deliveries;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

import org.json.JSONObject;

/**
 * Audit C12 (user 2026-09-25): the Worker-generated shared express fixtures that every client's
 * tests read, at deliveries/script/project/tests/fixtures/express. They are generated by the
 * Worker tools and never edited by hand here; a client that disagrees fails its own test.
 */
public final class SharedExpressFixtures {
    private SharedExpressFixtures() {}

    public static JSONObject load(String name) throws Exception {
        return new JSONObject(new String(Files.readAllBytes(path(name)), StandardCharsets.UTF_8));
    }

    public static Path path(String name) throws IOException {
        for (String base : new String[]{
                "../script/project/tests/fixtures/express",
                "script/project/tests/fixtures/express",
                "deliveries/script/project/tests/fixtures/express"}) {
            Path candidate = Paths.get(base, name);
            if (Files.isRegularFile(candidate)) return candidate;
        }
        throw new IOException("shared express fixture not found: " + name);
    }
}
